/* Portfolio presentation only. No account connection, storage or network calls. */
(()=>{'use strict';const root=document.querySelector('[data-studio-demo]');if(!root)return;const nav=root.querySelector('.demo-nav');const links=[...nav.querySelectorAll('[data-screen]')];const panels=[...root.querySelectorAll('.demo-view')];function show(id){const target=panels.find(p=>p.id===id);if(!target)return;panels.forEach(p=>p.hidden=p!==target);links.forEach(a=>{if(a.dataset.screen===id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});}links.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();show(a.dataset.screen);}));show('studio-today');const toggle=root.querySelector('[data-demo-theme]');toggle.hidden=false;toggle.addEventListener('click',()=>{const dark=root.dataset.theme!=='dark';root.dataset.theme=dark?'dark':'light';toggle.textContent=dark?toggle.dataset.light:toggle.dataset.dark;toggle.setAttribute('aria-pressed',String(dark));});})();
